p=Path(__file__).parent;m=json.loads((p/'original-exe.json').read_text());d=Path(m['path']).read_bytes();assert hashlib.sha256(d).hexdigest()==m['sha256']
def va(off):
 for _,v,r,n in m['sections']:
  if r<=off<r+n:return v+off-r
 raise ValueError(hex(off))
def off(a):
 for _,v,r,n in m['sections']:
  if v<=a<v+n:return r+a-v
 raise ValueError(hex(a))
def word(a):return struct.unpack_from('<I',d,off(a))[0]
rows=[]
for name in ['TESObjectARMO','TESObjectWEAP']:
 token=('.?AV'+name+'@@\0').encode();i=d.index(token);td=va(i-8);matches=[]
 for j in range(0,len(d)-20,4):
  if struct.unpack_from('<I',d,j+12)[0]!=td:continue
  sig,base,ctor=struct.unpack_from('<III',d,j)
  if sig!=0 or base!=0 or ctor!=0:continue
  col=va(j)
  needle=struct.pack('<I',col);k=0
  while (k:=d.find(needle,k))>=0:
   if k%4==0:
    vt=va(k+4)
    try:
     first=word(vt);quest=word(vt+0x78)
     if 0x401000<=first<0xa20000:matches.append({'vtable':hex(vt),'first':hex(first),'quest_virtual_78':hex(quest),'locator':hex(col)})
    except ValueError:pass
   k+=1
 assert len(matches)==1,(name,matches)
 rows.append({'class':name,'type_descriptor':hex(td),**matches[0]})
assert rows[1]['vtable']=='0xa45354' and all(x['quest_virtual_78']=='0x4d7030' for x in rows)
r={'passed':True,'executable_sha256':m['sha256'],'method':'MSVC RTTI primary vtable: exact TypeDescriptor, zero-offset CompleteObjectLocator, locator reference followed by executable slot0. WEAP crosscheck against prior primary vtable.','rows':rows};(p/'rtti-vtables.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2))

